    //   then find minimum of the parabola.
    int denom2 = std::max(Sp[d-1] + Sp[d+1] - 2*Sp[d], 1);

    //   fit parabola into (x1=d-1, y1=Sp[d-1]), (x2=d, y2=Sp[d]), (x3=d+1, y3=Sp[d+1])
    //   then find minimum of the parabola.
    int denom2 = std::max(Sp[d-1] + Sp[d+1] - 2*Sp[d], 1);
    d = d*DISP_SCALE + ((Sp[d-1] - Sp[d+1])*DISP_SCALE + denom2)/(denom2*2);
}
else

    //   then find minimum of the parabola.
    int denom2 = std::max(Sp[d-1] + Sp[d+1] - 2*Sp[d], 1);
    d = d*DISP_SCALE + ((Sp[d-1] - Sp[d+1])*DISP_SCALE + denom2)/(denom2*2);
}
else
    d *= DISP_SCALE;

